import React from "react";
import { ArrowsClockwise, type Icon } from "@phosphor-icons/react";
import { Loader } from "../loader/loader";
import { Tooltip } from "../tooltip/tooltip";
import { cn } from "../../utils/cn";
import { resolveVariant } from "../../utils/resolve-variant";
import { useLinkComponent } from "../../utils/link-provider";

/** Button variant definitions mapping shape, size, and variant names to their Tailwind classes. */
export const KUMO_BUTTON_VARIANTS = {
  shape: {
    base: {
      classes: "",
      description: "Default rectangular button shape",
    },
    square: {
      classes: "items-center justify-center p-0",
      description: "Square button for icon-only actions",
    },
    circle: {
      classes: "items-center justify-center p-0 rounded-full",
      description: "Circular button for icon-only actions",
    },
  },
  size: {
    xs: {
      classes: "h-5 gap-1 rounded-sm px-1.5 text-xs",
      description: "Extra small button for compact UIs",
    },
    sm: {
      classes: "h-6.5 gap-1 rounded-md px-2 text-xs",
      description: "Small button for secondary actions",
    },
    base: {
      classes: "h-9 gap-1.5 rounded-lg px-3 text-base",
      description: "Default button size",
    },
    lg: {
      classes: "h-10 gap-2 rounded-lg px-4 text-base",
      description: "Large button for primary CTAs",
    },
  },
  compactSize: {
    xs: { classes: "size-3.5" },
    sm: { classes: "size-6.5" },
    base: { classes: "size-9" },
    lg: { classes: "size-10" },
  },
  variant: {
    primary: {
      classes:
        "relative overflow-hidden bg-(--kumo-button-emphasis-bg) !text-white ring ring-(--kumo-button-emphasis-ring) focus:ring-(--kumo-button-emphasis-ring) focus-visible:ring-(--kumo-button-emphasis-ring) active:ring-(--kumo-button-emphasis-ring) disabled:opacity-50",
      description: "High-emphasis button for primary actions",
    },
    secondary: {
      classes:
        "bg-kumo-base !text-kumo-default ring not-disabled:hover:bg-kumo-tint disabled:bg-kumo-base/50 disabled:!text-kumo-default/70 ring-kumo-line data-[state=open]:bg-kumo-base",
      description: "Default button style for most actions",
    },
    ghost: {
      classes: "text-kumo-default hover:bg-kumo-tint shadow-none bg-inherit",
      description: "Minimal button with no background",
    },
    destructive: {
      classes:
        "relative overflow-hidden bg-(--kumo-button-emphasis-bg) !text-white ring ring-(--kumo-button-emphasis-ring) focus:ring-(--kumo-button-emphasis-ring) focus-visible:ring-(--kumo-button-emphasis-ring) active:ring-(--kumo-button-emphasis-ring) disabled:opacity-50",
      description: "Danger button for destructive actions like delete",
    },
    "secondary-destructive": {
      classes:
        "bg-kumo-base !text-kumo-danger ring not-disabled:hover:!text-kumo-danger not-disabled:hover:ring-kumo-danger/30 disabled:bg-kumo-base/50 disabled:!text-kumo-danger/70 ring-kumo-line data-[state=open]:bg-kumo-base",
      description:
        "Secondary button with destructive text for less prominent dangerous actions",
    },
    outline: {
      classes:
        "bg-transparent text-kumo-default ring ring-kumo-line transition-colors not-disabled:hover:text-kumo-strong not-disabled:hover:ring-kumo-focus/25",
      description: "Bordered button with transparent background",
    },
  },
} as const;

export const KUMO_BUTTON_DEFAULT_VARIANTS = {
  shape: "base",
  size: "base",
  variant: "secondary",
} as const;

// Derived types from KUMO_BUTTON_VARIANTS
export type KumoButtonShape = keyof typeof KUMO_BUTTON_VARIANTS.shape;
export type KumoButtonSize = keyof typeof KUMO_BUTTON_VARIANTS.size;
export type KumoButtonVariant = keyof typeof KUMO_BUTTON_VARIANTS.variant;

export interface KumoButtonVariantsProps {
  /**
   * Button shape.
   * - `"base"` — Default rectangular button
   * - `"square"` — Square button for icon-only actions
   * - `"circle"` — Circular button for icon-only actions
   * @default "base"
   */
  shape?: KumoButtonShape;
  /**
   * Button size.
   * - `"xs"` — Extra small for compact UIs
   * - `"sm"` — Small for secondary actions
   * - `"base"` — Default size
   * - `"lg"` — Large for primary CTAs
   * @default "base"
   */
  size?: KumoButtonSize;
  /**
   * Visual style of the button.
   * - `"primary"` — High-emphasis, brand-colored for primary actions
   * - `"secondary"` — Default style with border for most actions
   * - `"ghost"` — Minimal, no background for tertiary actions
   * - `"destructive"` — Danger button for destructive actions
   * - `"secondary-destructive"` — Secondary style with destructive text
   * - `"outline"` — Bordered with transparent background
   * @default "secondary"
   */
  variant?: KumoButtonVariant;
}

export function buttonVariants({
  variant = KUMO_BUTTON_DEFAULT_VARIANTS.variant,
  size = KUMO_BUTTON_DEFAULT_VARIANTS.size,
  shape = KUMO_BUTTON_DEFAULT_VARIANTS.shape,
}: KumoButtonVariantsProps = {}) {
  const isCompactShape = shape === "square" || shape === "circle";

  return cn(
    // Base styles
    "group flex w-max shrink-0 items-center font-medium select-none",
    "border-0 shadow-xs",
    "focus:ring-kumo-focus/50 focus:outline-none focus-visible:ring-2 focus-visible:ring-kumo-brand",
    "cursor-pointer",
    // Disabled state
    "disabled:cursor-not-allowed disabled:text-kumo-subtle",
    resolveVariant(
      KUMO_BUTTON_VARIANTS.size,
      size,
      KUMO_BUTTON_DEFAULT_VARIANTS.size,
    ).classes,
    resolveVariant(
      KUMO_BUTTON_VARIANTS.shape,
      shape,
      KUMO_BUTTON_DEFAULT_VARIANTS.shape,
    ).classes,
    isCompactShape &&
      resolveVariant(
        KUMO_BUTTON_VARIANTS.compactSize,
        size,
        KUMO_BUTTON_DEFAULT_VARIANTS.size,
      ).classes,
    resolveVariant(
      KUMO_BUTTON_VARIANTS.variant,
      variant,
      KUMO_BUTTON_DEFAULT_VARIANTS.variant,
    ).classes,
  );
}

// Normalize icon prop to support both React elements and component types
const renderIconNode = (IconComponent?: Icon | React.ReactNode) => {
  if (!IconComponent) return null;
  if (React.isValidElement(IconComponent)) return IconComponent;
  const Comp = IconComponent as React.ComponentType<Record<string, unknown>>;
  return <Comp />;
};

const getEmphasisToken = (variant: KumoButtonVariant) => {
  if (variant === "primary") return "var(--color-kumo-brand)";
  if (variant === "destructive") return "var(--color-kumo-danger)";
  return undefined;
};

const getEmphasisStyle = (variant: KumoButtonVariant) => {
  const token = getEmphasisToken(variant);
  if (!token) return undefined;

  return {
    "--kumo-button-emphasis-ring": `color-mix(in oklch, ${token}, black 10%)`,
    "--kumo-button-emphasis-bg": `color-mix(in oklch, ${token}, white 30%)`,
    "--kumo-button-emphasis-gradient-start": `color-mix(in oklch, ${token}, white 15%)`,
    "--kumo-button-emphasis-gradient-end": token,
  } satisfies React.CSSProperties & Record<`--${string}`, string>;
};

const ANCHOR_ONLY_PROPS = new Set([
  "href",
  "target",
  "rel",
  "download",
  "hrefLang",
  "media",
  "ping",
  "referrerPolicy",
  "linksExternal",
]);

const toDisabledButtonProps = (
  props: React.AnchorHTMLAttributes<HTMLAnchorElement>,
): React.ButtonHTMLAttributes<HTMLButtonElement> => {
  const result: Partial<React.AnchorHTMLAttributes<HTMLAnchorElement>> = {
    ...props,
  };
  for (const key of Object.keys(result)) {
    // event handlers are inert on a disabled button, and anchor-only attrs are invalid on it
    if (key.startsWith("on") || ANCHOR_ONLY_PROPS.has(key)) {
      delete result[key as keyof typeof result];
    }
  }
  return result as React.ButtonHTMLAttributes<HTMLButtonElement>;
};

const renderButtonContent = (
  variant: KumoButtonVariant,
  iconNode: React.ReactNode,
  children: React.ReactNode,
) => {
  const childNode =
    children != null ? <span className="contents">{children}</span> : null;

  if (!getEmphasisToken(variant)) {
    return (
      <>
        {iconNode}
        {childNode}
      </>
    );
  }

  return (
    <>
      <span
        aria-hidden="true"
        className="absolute inset-0 rounded-[inherit] bg-linear-to-b from-(--kumo-button-emphasis-gradient-start) to-(--kumo-button-emphasis-gradient-end) shadow-[inset_0_1px_0_0_var(--kumo-button-emphasis-bg)] group-hover:from-(--kumo-button-emphasis-bg)"
      />
      <span className="relative flex items-center gap-1.5">
        {iconNode}
        {childNode}
      </span>
    </>
  );
};

const getTitleLabel = (title: React.ReactNode) => {
  if (typeof title === "string") return title;
  if (typeof title === "number") return String(title);
  return undefined;
};

/**
 * Button component props.
 *
 * Uses a discriminated union on `shape` so that icon-only buttons
 * (`shape="square"` or `shape="circle"`) require an accessible name.
 *
 * @example
 * ```tsx
 * <Button variant="primary">Save</Button>
 * <Button variant="secondary" shape="square" icon={PlusIcon} aria-label="Add" />
 * <Button variant="destructive" loading>Deleting...</Button>
 * ```
 */
type ButtonBaseProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Content rendered inside the button. */
  children?: React.ReactNode;
  /** Additional CSS classes merged via `cn()`. */
  className?: string;
  /** Icon from `@phosphor-icons/react` or a React element. Rendered before children. */
  icon?: Icon | React.ReactNode;
  /** Shows a loading spinner and disables interaction. */
  loading?: boolean;
  /** When set, wraps the button in a Tooltip with this content. */
  title?: React.ReactNode;
};

type ButtonWithTextProps = ButtonBaseProps & {
  shape?: "base";
  size?: KumoButtonSize;
  variant?: KumoButtonVariant;
};

type IconOnlyButtonAccessibleNameProps =
  | {
      /** Required for icon-only buttons to provide an accessible label for screen readers. */
      "aria-label": string;
      "aria-labelledby"?: string;
    }
  | {
      "aria-label"?: string;
      /** References an element that provides the accessible label for screen readers. */
      "aria-labelledby": string;
    }
  | {
      /** Used as tooltip content and as a fallback accessible label when no children are provided. */
      title: string | number;
      "aria-label"?: string;
      "aria-labelledby"?: string;
    };

type IconOnlyButtonProps = ButtonBaseProps &
  IconOnlyButtonAccessibleNameProps & {
    shape: "square" | "circle";
    size?: KumoButtonSize;
    variant?: KumoButtonVariant;
  };

export type ButtonProps = ButtonWithTextProps | IconOnlyButtonProps;

export type RefreshButtonProps = Omit<
  IconOnlyButtonProps,
  "children" | "icon" | "shape"
>;

/**
 * LinkButton component props — renders an anchor styled as a button.
 *
 * @example
 * ```tsx
 * <LinkButton href="/docs" variant="ghost" icon={BookIcon}>Docs</LinkButton>
 * <LinkButton href="https://example.com" external>Visit Site</LinkButton>
 * ```
 */
export type LinkButtonProps = React.AnchorHTMLAttributes<HTMLAnchorElement> &
  KumoButtonVariantsProps & {
    /** Content rendered inside the link button. */
    children?: React.ReactNode;
    /** Additional CSS classes merged via `cn()`. */
    className?: string;
    /** When `true`, the button is disabled. We render an actual html button with `disabled` attribute. */
    disabled?: boolean;
    /** Icon from `@phosphor-icons/react` or a React element. Rendered before children. */
    icon?: Icon | React.ReactNode;
    /** When `true`, opens in a new tab with `rel="noopener noreferrer"`. */
    external?: boolean;
    linksExternal?: boolean;
  };

/**
 * Primary action trigger. Supports multiple variants, sizes, shapes, icons, and loading state.
 *
 * @example
 * ```tsx
 * <Button variant="primary">Save</Button>
 * <Button variant="secondary" icon={PlusIcon}>Create Worker</Button>
 * ```
 */
export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      children,
      className,
      disabled,
      loading,
      shape = "base",
      size = "base",
      variant = "secondary",
      icon: IconComponent,
      style,
      title,
      ...props
    },
    ref,
  ) => {
    const { type, ...restProps } = props;
    const emphasisStyle = getEmphasisStyle(variant);
    const titleLabel = getTitleLabel(title);
    const buttonProps = {
      ...restProps,
      ...(!React.Children.count(children) &&
        !restProps["aria-label"] &&
        !restProps["aria-labelledby"] &&
        titleLabel && { "aria-label": titleLabel }),
    };
    const iconNode = loading ? (
      <Loader size={size === "lg" ? 16 : 14} />
    ) : (
      renderIconNode(IconComponent)
    );

    const button = (
      <button
        ref={ref}
        data-kumo-component="Button"
        className={cn(
          buttonVariants({ variant, size, shape }),
          disabled && "cursor-not-allowed opacity-50",
          className,
        )}
        disabled={loading || disabled}
        style={emphasisStyle ? { ...emphasisStyle, ...style } : style}
        type={type ?? "button"}
        {...buttonProps}
      >
        {renderButtonContent(variant, iconNode, children)}
      </button>
    );

    if (title && (disabled || loading)) {
      return (
        <Tooltip content={title} render={<span className="inline-flex" />}>
          {button}
        </Tooltip>
      );
    }

    if (title) {
      return <Tooltip content={title} render={button} />;
    }

    return button;
  },
);

Button.displayName = "Button";

/**
 * Square button with a rotating arrows icon, used to trigger data refresh actions.
 *
 * @example
 * ```tsx
 * <RefreshButton loading={isRefreshing} onClick={refresh} />
 * ```
 */
export const RefreshButton = ({
  "aria-label": ariaLabel = "Refresh",
  loading,
  ...props
}: RefreshButtonProps) => (
  <Button shape="square" aria-label={ariaLabel} {...props}>
    <ArrowsClockwise
      className={cn({
        "animate-refresh": loading,
        "size-4.5": props.size === "base" || !props.size,
        "size-4": props.size === "sm",
        "size-5": props.size === "lg",
      })}
    />
  </Button>
);

/**
 * Anchor element styled as a button. Integrates with `LinkProvider` for framework routing.
 *
 * @example
 * ```tsx
 * <LinkButton href="/settings" variant="ghost">Settings</LinkButton>
 * ```
 */
export const LinkButton = React.forwardRef<HTMLAnchorElement, LinkButtonProps>(
  (
    {
      children,
      className,
      disabled = false,
      external,
      href,
      shape = "base",
      size = "base",
      variant = "ghost",
      icon: IconComponent,
      style,
      title,
      // linksExternal = false,
      ...props
    },
    ref,
  ) => {
    const LinkComponent = useLinkComponent();
    const emphasisStyle = getEmphasisStyle(variant);
    const externalProps = external
      ? { target: "_blank", rel: "noopener noreferrer" }
      : {};

    if (disabled) {
      // ref is intentionally not forwarded: it's typed for the anchor, but the disabled state renders a button
      return (
        <Button
          {...toDisabledButtonProps(props)}
          className={cn("select-text", className)}
          data-kumo-component="LinkButton"
          disabled
          icon={IconComponent}
          shape={shape as "base"}
          size={size}
          style={style}
          title={title}
          variant={variant}
        >
          {children}
        </Button>
      );
    }

    const link = (
      <LinkComponent
        ref={ref}
        data-kumo-component="LinkButton"
        className={cn(
          buttonVariants({ variant, size, shape }),
          "flex items-center no-underline! select-text",
          className,
        )}
        href={href}
        style={emphasisStyle ? { ...emphasisStyle, ...style } : style}
        to={typeof href === "string" ? href : undefined}
        {...externalProps}
        {...props}
      >
        {renderButtonContent(variant, renderIconNode(IconComponent), children)}
      </LinkComponent>
    );

    if (title) {
      return <Tooltip content={title} render={link} />;
    }

    return link;
  },
);

LinkButton.displayName = "LinkButton";

import { cn } from "../../utils/cn";
import { resolveVariant } from "../../utils/resolve-variant";
import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react";
import { Input as BaseInput } from "@base-ui/react/input";
import {
  Field,
  normalizeFieldError,
  type FieldErrorMatch,
} from "../field/field";

/** Input size and variant definitions mapping names to their Tailwind classes. */
export const KUMO_INPUT_VARIANTS = {
  size: {
    xs: {
      classes: "h-5 gap-1 rounded-sm px-1.5 text-xs",
      description: "Extra small input for compact UIs",
    },
    sm: {
      classes: "h-6.5 gap-1 rounded-md px-2 text-xs",
      description: "Small input for secondary fields",
    },
    base: {
      classes: "h-9 gap-1.5 rounded-lg px-3 text-base",
      description: "Default input size",
    },
    lg: {
      classes: "h-10 gap-2 rounded-lg px-4 text-base",
      description: "Large input for prominent fields",
    },
  },
  variant: {
    default: {
      classes: "focus:ring-kumo-focus/50 focus:ring-[1.5px]",
      description: "Default input appearance",
    },
    error: {
      classes: "!ring-kumo-danger focus:ring-kumo-danger/50 focus:ring-[1.5px]",
      description: "Error state for validation failures",
    },
  },
} as const;

export const KUMO_INPUT_DEFAULT_VARIANTS = {
  size: "base",
  variant: "default",
} as const;

export const KUMO_INPUT_STYLING = {
  dimensions: {
    xs: { height: 20, paddingX: 6, fontSize: 12, borderRadius: 2, width: 160 },
    sm: { height: 26, paddingX: 8, fontSize: 12, borderRadius: 6, width: 200 },
    base: {
      height: 36,
      paddingX: 12,
      fontSize: 16,
      borderRadius: 8,
      width: 280,
    },
    lg: { height: 40, paddingX: 16, fontSize: 16, borderRadius: 8, width: 320 },
  },
  baseTokens: {
    background: "color-secondary",
    text: "text-color-surface",
    placeholder: "text-color-muted",
    ring: "color-border",
  },
  stateTokens: {
    focus: { ring: "color-active" },
    error: { ring: "color-error" },
    disabled: { opacity: 0.5, text: "text-color-muted" },
  },
} as const;

// Derived types from KUMO_INPUT_VARIANTS
export type KumoInputSize = keyof typeof KUMO_INPUT_VARIANTS.size;
export type KumoInputVariant = keyof typeof KUMO_INPUT_VARIANTS.variant;

export interface KumoInputVariantsProps {
  /**
   * Input size.
   * - `"xs"` — Extra small for compact UIs
   * - `"sm"` — Small for secondary fields
   * - `"base"` — Default size
   * - `"lg"` — Large for prominent fields
   * @default "base"
   */
  size?: KumoInputSize;
  /**
   * Visual variant.
   * - `"default"` — Standard input
   * - `"error"` — Error state for validation failures
   * @default "default"
   */
  variant?: KumoInputVariant;
  parentFocusIndicator?: boolean;
  focusIndicator?: boolean;
}

// Omit native `size` attribute (number) to avoid conflict with our custom `size` variant
type BaseInputProps = Omit<ComponentPropsWithoutRef<typeof BaseInput>, "size">;

export function inputVariants({
  variant = KUMO_INPUT_DEFAULT_VARIANTS.variant,
  size = KUMO_INPUT_DEFAULT_VARIANTS.size,
  parentFocusIndicator = false,
  focusIndicator = false,
}: KumoInputVariantsProps = {}) {
  return cn(
    // Base styles
    "border-0 bg-kumo-control text-kumo-default ring ring-kumo-line outline-none focus:outline-none",
    // Disabled state and placeholder styles (using vanilla CSS class for Chrome compatibility)
    "kumo-input-placeholder disabled:text-kumo-disabled",
    // Apply size styles from KUMO_INPUT_VARIANTS
    resolveVariant(
      KUMO_INPUT_VARIANTS.size,
      size,
      KUMO_INPUT_DEFAULT_VARIANTS.size,
    ).classes,
    // Apply variant styles from KUMO_INPUT_VARIANTS
    resolveVariant(
      KUMO_INPUT_VARIANTS.variant,
      variant,
      KUMO_INPUT_DEFAULT_VARIANTS.variant,
    ).classes,
    // Focus state handling
    parentFocusIndicator &&
      (variant === "error"
        ? "focus-within:ring-[1.5px] focus-within:ring-kumo-danger/50"
        : "focus-within:ring-[1.5px] focus-within:ring-kumo-focus/50"),
    focusIndicator &&
      (variant === "error"
        ? "focus:ring-[1.5px] focus:ring-kumo-danger/50"
        : "focus:ring-[1.5px] focus:ring-kumo-focus/50"),
  );
}

export const Input = forwardRef<HTMLInputElement, InputProps>((props, ref) => {
  const {
    className,
    size = "base",
    variant: variantProp,
    label,
    labelTooltip,
    description,
    error,
    passwordManagerIgnore = false,
    ...inputProps
  } = props;

  // Deprecation warning for variant="error"
  if (process.env.NODE_ENV !== "production" && variantProp === "error") {
    console.warn(
      '[Kumo Input]: variant="error" is deprecated. ' +
        "Error styling is now automatically applied when the `error` prop is truthy. " +
        "Simply remove the variant prop and pass an error message instead.",
    );
  }

  // Auto-apply error styling when error prop is truthy
  // Explicit variant prop takes precedence for backwards compatibility
  const variant = variantProp ?? (error ? "error" : "default");

  // Extract required from inputProps to pass to Field for label decoration
  const { required } = inputProps;

  // A11y enforcement: warn in dev if no accessible name provided
  if (process.env.NODE_ENV !== "production") {
    const hasLabel = Boolean(label);
    const hasAriaLabel = Boolean(inputProps["aria-label"]);
    const hasAriaLabelledBy = Boolean(inputProps["aria-labelledby"]);

    if (!hasLabel && !hasAriaLabel && !hasAriaLabelledBy) {
      console.warn(
        "[Kumo Input]: Input must have an accessible name. Provide either:\n" +
          "  - label prop: <Input label='Email' />\n" +
          "  - aria-label: <Input aria-label='Email address' />\n" +
          "  - aria-labelledby for custom label association",
      );
    }
  }

  const input = (
    <BaseInput
      ref={ref}
      className={cn(
        inputVariants({ size, variant, focusIndicator: true }),
        passwordManagerIgnore && "keeper-ignore",
        className,
      )}
      {...(passwordManagerIgnore
        ? {
            "data-1p-ignore": "true",
            "data-bwignore": "true",
            "data-form-type": "other",
            "data-lpignore": "true",
          }
        : {})}
      {...inputProps}
    />
  );

  // Render with Field wrapper if label, error, or description is provided
  if (label || error || description) {
    return (
      <Field
        label={label}
        required={required}
        labelTooltip={labelTooltip}
        description={description}
        error={normalizeFieldError(error)}
      >
        {input}
      </Field>
    );
  }

  // Render bare input without Field wrapper
  return input;
});

Input.displayName = "Input";

/**
 * Input component props with accessibility guidance.
 *
 * **Accessible Name Required:** Input should have one of:
 * 1. `label` prop (recommended) - enables Field wrapper with label/description/error
 * 2. `placeholder` + `aria-label` - for bare inputs with visual placeholder
 * 3. `aria-labelledby` - for custom label association
 *
 * Missing accessible names will trigger console warnings in development.
 *
 * @example
 * // Recommended: Built-in Field wrapper
 * <Input label="Email" placeholder="you@example.com" />
 *
 * @example
 * // Bare input with placeholder and aria-label
 * <Input placeholder="Search..." aria-label="Search products" />
 *
 * @example
 * // Custom label association
 * <label id="email-label">Email</label>
 * <Input aria-labelledby="email-label" />
 *
 * @example
 * // With description and error
 * <Input
 *   label="Password"
 *   description="Must be at least 8 characters"
 *   error="Password is too short"
 * />
 */
export type InputProps = Pick<KumoInputVariantsProps, "size" | "variant"> &
  BaseInputProps & {
    /** Label content for the input (enables Field wrapper) - can be a string or any React node */
    label?: ReactNode;
    /** Tooltip content to display next to the label via an info icon */
    labelTooltip?: ReactNode;
    /** Helper text displayed below the input */
    description?: ReactNode;
    /** Error message or validation error object */
    error?: string | { message: ReactNode; match: FieldErrorMatch };
    /** Suppress browser extension password manager overlays on non-credential inputs. */
    passwordManagerIgnore?: boolean;
  };

/**
 * @module @cloudflare/kumo
 *
 * Cloudflare's React component library built on Base UI and Tailwind CSS v4.
 *
 * **Key rules:**
 * - Use **semantic tokens only** (`bg-kumo-base`, `text-kumo-default`, etc.) — never raw Tailwind colors.
 * - **No `dark:` variant** — light/dark mode is handled automatically via CSS `light-dark()`.
 * - Merge custom classes with the `cn()` utility exported from this package.
 * - Wrap your app with the kumo CSS import: `import "@cloudflare/kumo/styles"`.
 *
 * **Component categories:**
 * - **Action:** Button, ClipboardText
 * - **Display:** Badge, Breadcrumbs, Code, Empty, LayerCard, Meter, Surface (deprecated), Text
 * - **Feedback:** Banner, Loader, Toast
 * - **Input:** Checkbox, Combobox, DateRangePicker, Field, Input, Radio, Select, SensitiveInput, Switch
 * - **Layout:** Grid, Surface
 * - **Navigation:** CommandPalette, MenuBar, Pagination, Tabs
 * - **Overlay:** Dialog, DropdownMenu, Popover, Tooltip
 * - **Other:** Label, Link
 *
 * **Blocks** (composite page-level components) are NOT exported here.
 * Install them via the CLI: `npx @cloudflare/kumo add <block-name>`.
 *
 * **AI resources:** See `@cloudflare/kumo/ai/component-registry.json` for full
 * component metadata including prop descriptions, variant values, and examples.
 *
 * @see {@link https://kumo-ui.com} — Documentation site
 */

