/**
 * Dialog component props — the modal content panel.
 *
 * @example
 * ```tsx
 * <Dialog.Root>
 *   <Dialog.Trigger render={(p) => <Button {...p}>Open</Button>} />
 *   <Dialog className="p-8">
 *     <Dialog.Title>Confirm Action</Dialog.Title>
 *     <Dialog.Description>Are you sure?</Dialog.Description>
 *     <Dialog.Close render={(p) => <Button {...p}>Cancel</Button>} />
 *   </Dialog>
 * </Dialog.Root>
 * ```
 */
export type DialogProps = KumoDialogVariantsProps & {
  /** Additional CSS classes merged via `cn()`. */
  className?: string;
  /** Dialog content (typically Title, Description, Close, and action buttons). */
  children: ReactNode;
  /** Inline styles. */
  style?: CSSProperties;
  /**
   * Container element for the portal. Use this to render the dialog inside
   * a Shadow DOM or custom container. Overrides `KumoPortalProvider` context.
   * @default document.body (or KumoPortalProvider container if set)
   */
  container?: PortalContainer;
};

/**
 * Modal dialog overlay with backdrop. Compound component with `Dialog.Root`,
 * `Dialog.Trigger`, `Dialog.Title`, `Dialog.Description`, and `Dialog.Close`.
 *
 * @example
 * ```tsx
 * <Dialog.Root>
 *   <Dialog.Trigger render={(p) => <Button {...p}>Delete</Button>} />
 *   <Dialog className="p-8">
 *     <Dialog.Title>Delete Item</Dialog.Title>
 *     <Dialog.Description>This action cannot be undone.</Dialog.Description>
 *     <Dialog.Close render={(p) => <Button variant="destructive" {...p}>Delete</Button>} />
 *   </Dialog>
 * </Dialog.Root>
 * ```
 *
 * @example Alert Dialog for destructive actions
 * ```tsx
 * <Dialog.Root role="alertdialog">
 *   <Dialog.Trigger render={(p) => <Button variant="destructive" {...p}>Delete Project</Button>} />
 *   <Dialog className="p-8">
 *     <Dialog.Title>Delete Project?</Dialog.Title>
 *     <Dialog.Description>This action cannot be undone.</Dialog.Description>
 *     <Dialog.Close render={(p) => <Button variant="secondary" {...p}>Cancel</Button>} />
 *     <Dialog.Close render={(p) => <Button variant="destructive" {...p}>Delete</Button>} />
 *   </Dialog>
 * </Dialog.Root>
 * ```
 */
function DialogContent({
  className,
  children,
  style,
  size = KUMO_DIALOG_DEFAULT_VARIANTS.size,
  container: containerProp,
}: DialogProps) {
  const role = useDialogRole();
  const contextContainer = usePortalContainer();
  const container = containerProp ?? contextContainer ?? undefined;

  const BasePortal =
    role === "alertdialog" ? AlertDialogBase.Portal : DialogBase.Portal;
  const BaseBackdrop =
    role === "alertdialog" ? AlertDialogBase.Backdrop : DialogBase.Backdrop;
  const BasePopup =
    role === "alertdialog" ? AlertDialogBase.Popup : DialogBase.Popup;

  return (
    <BasePortal container={container}>
      <BaseBackdrop className="fixed inset-0 bg-kumo-recessed opacity-80 transition-all duration-150 data-ending-style:opacity-0 data-starting-style:opacity-0" />
      <LayerCard
        render={<BasePopup />}
        className={cn(dialogVariants({ size }), className)}
        style={
          {
            transitionProperty: "scale, opacity",
            transitionTimingFunction:
              "var(--default-transition-timing-function)",
            "--tw-shadow":
              "0 20px 25px -5px rgb(0 0 0 / 0.03), 0 8px 10px -6px rgb(0 0 0 / 0.03)",
            ...style,
          } as CSSProperties
        }
      >
        {children}
      </LayerCard>
    </BasePortal>
  );
}

// ============================================================================
// Dialog Root
// ============================================================================

type BaseDialogRootProps = ComponentPropsWithoutRef<typeof DialogBase.Root>;
type BaseAlertDialogRootProps = ComponentPropsWithoutRef<
  typeof AlertDialogBase.Root
>;

type StandardDialogRootProps = BaseDialogRootProps & {
  /**
   * The ARIA role for the dialog.
   * - `"dialog"` — Standard dialog for general-purpose modals. Dismissible via outside click by default.
   * - `"alertdialog"` — Alert dialog for destructive or confirmation flows. Not dismissible via outside click.
   *
   * Use `role="alertdialog"` for:
   * - Destructive actions (delete, discard, remove)
   * - Confirmation dialogs requiring explicit user acknowledgment
   * - Actions that cannot be undone
   *
   * @default "dialog"
   */
  role?: "dialog";
};

type AlertDialogRootProps = BaseAlertDialogRootProps & {
  role: "alertdialog";
};

export type DialogRootProps = StandardDialogRootProps | AlertDialogRootProps;

function DialogRoot(props: DialogRootProps) {
  if (props.role === "alertdialog") {
    const { children, role, ...rootProps } = props;

    return (
      <DialogRoleContext.Provider value={role}>
        <AlertDialogBase.Root {...rootProps}>{children}</AlertDialogBase.Root>
      </DialogRoleContext.Provider>
    );
  }

  const {
    children,
    role = KUMO_DIALOG_DEFAULT_VARIANTS.role,
    ...rootProps
  } = props;

  return (
    <DialogRoleContext.Provider value={role}>
      <DialogBase.Root {...rootProps}>{children}</DialogBase.Root>
    </DialogRoleContext.Provider>
  );
}

DialogRoot.displayName = "Dialog.Root";

// ============================================================================
// Dialog Trigger
// ============================================================================

type BaseDialogTriggerProps = ComponentPropsWithoutRef<
  typeof DialogBase.Trigger
>;
type BaseAlertDialogTriggerProps = ComponentPropsWithoutRef<
  typeof AlertDialogBase.Trigger
>;

export type DialogTriggerProps =
  BaseDialogTriggerProps | BaseAlertDialogTriggerProps;

function DialogTrigger({ children, ...props }: DialogTriggerProps) {
  const role = useDialogRole();

  if (role === "alertdialog") {
    return (
      <AlertDialogBase.Trigger
        data-kumo-component="Dialog"
        data-kumo-part="trigger"
        {...(props as BaseAlertDialogTriggerProps)}
      >
        {children}
      </AlertDialogBase.Trigger>
    );
  }

  return (
    <DialogBase.Trigger
      data-kumo-component="Dialog"
      data-kumo-part="trigger"
      {...props}
    >
      {children}
    </DialogBase.Trigger>
  );
}

DialogTrigger.displayName = "Dialog.Trigger";

// ============================================================================
// Dialog Title
// ============================================================================

type BaseDialogTitleProps = ComponentPropsWithoutRef<typeof DialogBase.Title>;

export type DialogTitleProps = BaseDialogTitleProps;

function DialogTitle({ className, ...props }: DialogTitleProps) {
  const role = useDialogRole();
  const BaseTitle =
    role === "alertdialog" ? AlertDialogBase.Title : DialogBase.Title;
  return <BaseTitle className={className} {...props} />;
}

DialogTitle.displayName = "Dialog.Title";

// ============================================================================
// Dialog Description
// ============================================================================

type BaseDialogDescriptionProps = ComponentPropsWithoutRef<
  typeof DialogBase.Description
>;

export type DialogDescriptionProps = BaseDialogDescriptionProps;

function DialogDescription({ className, ...props }: DialogDescriptionProps) {
  const role = useDialogRole();
  const BaseDescription =
    role === "alertdialog"
      ? AlertDialogBase.Description
      : DialogBase.Description;
  return <BaseDescription className={className} {...props} />;
}

DialogDescription.displayName = "Dialog.Description";

// ============================================================================
// Dialog Close
// ============================================================================

type BaseDialogCloseProps = ComponentPropsWithoutRef<typeof DialogBase.Close>;

export type DialogCloseProps = BaseDialogCloseProps;

function DialogClose({ children, ...props }: DialogCloseProps) {
  const role = useDialogRole();
  const BaseClose =
    role === "alertdialog" ? AlertDialogBase.Close : DialogBase.Close;
  return (
    <BaseClose data-kumo-component="Dialog" data-kumo-part="close" {...props}>
      {children}
    </BaseClose>
  );
}

DialogClose.displayName = "Dialog.Close";

// ============================================================================
// Compound Component Export
// ============================================================================

const Dialog = Object.assign(DialogContent, {
  Root: DialogRoot,
  Trigger: DialogTrigger,
  Title: DialogTitle,
  Description: DialogDescription,
  Close: DialogClose,
});

export {
  Dialog,
  DialogRoot,
  DialogTrigger,
  DialogTitle,
  DialogDescription,
  DialogClose,
};

import { Tooltip as TooltipBase } from "@base-ui/react/tooltip";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "../../utils/cn";
import { resolveVariant } from "../../utils/resolve-variant";
import {
  usePortalContainer,
  type PortalContainer,
} from "../../utils/portal-provider";

/** Tooltip side variant definitions mapping positions to their Tailwind classes. */
export const KUMO_TOOLTIP_VARIANTS = {
  side: {
    top: {
      classes: "",
      description: "Tooltip appears above the trigger",
    },
    bottom: {
      classes: "",
      description: "Tooltip appears below the trigger",
    },
    left: {
      classes: "",
      description: "Tooltip appears to the left of the trigger",
    },
    right: {
      classes: "",
      description: "Tooltip appears to the right of the trigger",
    },
  },
} as const;

export const KUMO_TOOLTIP_DEFAULT_VARIANTS = {
  side: "top",
} as const;

// Derived types from KUMO_TOOLTIP_VARIANTS
export type KumoTooltipSide = keyof typeof KUMO_TOOLTIP_VARIANTS.side;

export interface KumoTooltipVariantsProps {
  /**
   * Preferred side of the trigger to render the tooltip.
   * - `"top"` — Tooltip appears above the trigger
   * - `"bottom"` — Tooltip appears below the trigger
   * - `"left"` — Tooltip appears to the left of the trigger
   * - `"right"` — Tooltip appears to the right of the trigger
   * @default "top"
   */
  side?: KumoTooltipSide;
}

export function tooltipVariants({
  side = KUMO_TOOLTIP_DEFAULT_VARIANTS.side,
}: KumoTooltipVariantsProps = {}) {
  return cn(
    // Base styles
    "flex origin-[var(--transform-origin)] flex-col rounded-md bg-kumo-base px-2.5 py-1.5 text-sm text-kumo-default",
    "shadow-lg shadow-kumo-tip-shadow outline-1 outline-kumo-fill",
    "transition-[transform,scale,opacity] duration-150",
    "data-[starting-style]:scale-90 data-[starting-style]:opacity-0",
    "data-[ending-style]:scale-90 data-[ending-style]:opacity-0",
    "data-[instant]:duration-0",
    // Apply side-specific styles (currently none, but extensible)
    resolveVariant(
      KUMO_TOOLTIP_VARIANTS.side,
      side,
      KUMO_TOOLTIP_DEFAULT_VARIANTS.side,
    ).classes,
  );
}

export const TooltipProvider = TooltipBase.Provider;

type BaseTooltipProps = ComponentPropsWithoutRef<typeof TooltipBase.Root>;

type TriggerProps = ComponentPropsWithoutRef<typeof TooltipBase.Trigger>;

/** Alignment options for tooltip positioning. Source: PositionerProps["align"] */
type TooltipAlign = "start" | "center" | "end";

/**
 * Tooltip component props.
 *
 * @example
 * ```tsx
 * <Tooltip content="Add new item" render={<Button shape="square" icon={PlusIcon} />}>
 *   Add
 * </Tooltip>
 * ```
 */
export type TooltipProps = BaseTooltipProps &
  KumoTooltipVariantsProps & {
    /**
     * Alignment on the axis perpendicular to `side`.
     * - `"start"` — Align to the start edge
     * - `"center"` — Center-aligned
     * - `"end"` — Align to the end edge
     */
    align?: TooltipAlign;
    /**
     * @deprecated Use the `render` prop instead.
     * @example `<Tooltip render={<Button />}>Label</Tooltip>` instead of `<Tooltip asChild><Button>Label</Button></Tooltip>`
     */
    asChild?: boolean;
    /** Additional CSS classes merged via `cn()`. */
    className?: string;
    /** Content to display inside the tooltip popup. */
    content: ReactNode;
    /**
     * Container element for the portal. Use this to render the tooltip inside
     * a Shadow DOM or custom container. Overrides `KumoPortalProvider` context.
     * @default document.body (or KumoPortalProvider container if set)
     */
    container?: PortalContainer;
    /**
     * How long to wait before closing the tooltip. Specified in milliseconds.
     * @default 0
     */
    closeDelay?: number;
    /**
     * How long to wait before opening the tooltip. Specified in milliseconds.
     * @default 600
     */
    delay?: number;
    /**
     * Element to render as the tooltip trigger. Children are passed to this element.
     * @example `<Tooltip content="Save" render={<Button />}>Save</Tooltip>`
     */
    render?: TriggerProps["render"];
  };

/**
 * Accessible popup that shows additional information on hover/focus.
 * Wrap your app or section with `<TooltipProvider>` to enable delay grouping.
 *
 * @example
 * ```tsx
 * <Tooltip content="Save changes" render={<Button variant="primary" />}>
 *   Save
 * </Tooltip>
 * ```
 */
export function Tooltip({
  content,
  children,
  align,
  asChild,
  render,
  side,
  className,
  container: containerProp,
  closeDelay,
  delay,
  ...props
}: TooltipProps) {
  const contextContainer = usePortalContainer();
  const container = containerProp ?? contextContainer ?? undefined;

  // Support both render prop (preferred) and deprecated asChild pattern
  // When using asChild, children IS the render element, so don't pass it as children
  const resolvedRender =
    render ?? (asChild ? (children as TriggerProps["render"]) : undefined);
  const shouldUseRender = resolvedRender !== undefined;

  return (
    <TooltipBase.Root {...props}>
      <TooltipBase.Trigger
        closeDelay={closeDelay}
        delay={delay}
        className={cn(
          // Defensive resets when rendering as button wrapper (not render/asChild)
          // These prevent global button styles from polluting the trigger
          // Consumer styles passed via className will override these.
          !shouldUseRender &&
            "m-0 inline-flex h-auto min-h-0 items-center border-none bg-transparent p-0 leading-[0] shadow-none",
          // Tooltip triggers are disclosure elements, not actions — override
          // cursor: pointer (e.g. from Button used via render prop) so the
          // trigger doesn't appear clickable
          "cursor-default",
          className,
        )}
        render={resolvedRender}
      >
        {asChild ? undefined : (children as ReactNode)}
      </TooltipBase.Trigger>
      <TooltipBase.Portal container={container}>
        <TooltipBase.Positioner
          align={align}
          side={side}
          sideOffset={10}
          className="max-w-[var(--available-width)]"
        >
          <TooltipBase.Popup
            className={cn(
              "flex origin-[var(--transform-origin)] flex-col rounded-md bg-kumo-base px-2.5 py-1.5 text-sm text-kumo-default",
              "shadow-lg shadow-kumo-tip-shadow outline outline-kumo-fill",
              "transition-[transform,scale,opacity] duration-150",
              "data-[starting-style]:scale-90 data-[starting-style]:opacity-0",
              "data-[ending-style]:scale-90 data-[ending-style]:opacity-0",
              "data-[instant]:duration-0",
              "kumo-tooltip-popup",
            )}
          >
            <TooltipBase.Arrow
              className={cn(
                "flex",
                "data-[side=bottom]:top-[-8px]",
                "data-[side=left]:right-[-13px] data-[side=left]:rotate-90",
                "data-[side=right]:left-[-13px] data-[side=right]:-rotate-90",
                "data-[side=top]:bottom-[-8px] data-[side=top]:rotate-180",
              )}
            >
              <ArrowSvg />
            </TooltipBase.Arrow>
            {content}
          </TooltipBase.Popup>
        </TooltipBase.Positioner>
      </TooltipBase.Portal>
    </TooltipBase.Root>
  );
}

/**
 * Arrow SVG with three paths for proper border rendering in both light and dark modes.
 * This approach matches Base UI's tooltip implementation.
 *
 * The three paths are:
 * 1. ArrowFill - The main arrow body, matches tooltip background
 * 2. ArrowOuterStroke - Border visible in light mode only (transparent in dark)
 * 3. ArrowInnerStroke - Border visible in dark mode only (transparent in light)
 *
 * This is necessary because the outer and inner stroke paths have different geometries,
 * and using both ensures the arrow border aligns perfectly with the tooltip's outline
 * in both color modes.
 *
 * @see https://base-ui.com/react/components/tooltip
 */
function ArrowSvg(props: React.ComponentProps<"svg">) {
  return (
    <svg width="20" height="10" viewBox="0 0 20 10" fill="none" {...props}>
      <path
        d="M9.66437 2.60207L4.80758 6.97318C4.07308 7.63423 3.11989 8 2.13172 8H0V10H20V8H18.5349C17.5468 8 16.5936 7.63423 15.8591 6.97318L11.0023 2.60207C10.622 2.2598 10.0447 2.25979 9.66437 2.60207Z"
        className="fill-kumo-base"
      />
      <path
        d="M8.99542 1.85876C9.75604 1.17425 10.9106 1.17422 11.6713 1.85878L16.5281 6.22989C17.0789 6.72568 17.7938 7.00001 18.5349 7.00001L15.89 7L11.0023 2.60207C10.622 2.2598 10.0447 2.2598 9.66436 2.60207L4.77734 7L2.13171 7.00001C2.87284 7.00001 3.58774 6.72568 4.13861 6.22989L8.99542 1.85876Z"
        className="fill-kumo-tip-shadow"
      />
      <path
        d="M10.3333 3.34539L5.47654 7.71648C4.55842 8.54279 3.36693 9 2.13172 9H0V8H2.13172C3.11989 8 4.07308 7.63423 4.80758 6.97318L9.66437 2.60207C10.0447 2.25979 10.622 2.2598 11.0023 2.60207L15.8591 6.97318C16.5936 7.63423 17.5468 8 18.5349 8H20V9H18.5349C17.2998 9 16.1083 8.54278 15.1901 7.71648L10.3333 3.34539Z"
        className="fill-kumo-tip-stroke"
      />
    </svg>
  );
}

import {
  createContext,
  forwardRef,
  type AnchorHTMLAttributes,
  type ForwardRefExoticComponent,
  type ReactNode,
  type RefAttributes,
  useContext,
} from "react";

type LinkComponentProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
  /**
   * @deprecated Use `href` instead. The `to` prop is a routing-framework concept
   * (e.g. React Router) that does not belong on a presentational component.
   *
   * If your application uses a client-side router, configure the `LinkProvider`
   * with a wrapper component that maps `href` to your router's navigation prop:
   *
   * ```tsx
   * const AppLink = forwardRef(({ href, ...rest }, ref) => (
   *   <ReactRouterLink ref={ref} to={href} {...rest} />
   * ));
   *
   * <LinkProvider component={AppLink}>
   *   <App />
   * </LinkProvider>
   * ```
   */
  to?: string;
};

const DefaultLinkComponent = forwardRef<HTMLAnchorElement, LinkComponentProps>(
  function DefaultAnchor({ to, href, ...rest }, ref) {
    // Children and other content props are passed via ...rest spread
    // oxlint-disable-next-line anchor-has-content
    return <a ref={ref} href={href ?? to ?? undefined} {...rest} />;
  },
);

type ForwardLinkComponent = ForwardRefExoticComponent<
  LinkComponentProps & RefAttributes<HTMLAnchorElement>
>;

const LinkComponentContext =
  createContext<ForwardLinkComponent>(DefaultLinkComponent);

export function useLinkComponent() {
  return useContext(LinkComponentContext);
}

/**
 * Provides a custom link component for all Kumo Link instances in the tree.
 *
 * Use this to integrate framework-specific routing (React Router, Next.js, etc.)
 * while keeping Kumo's Link component framework-agnostic.
 *
 * Your custom component receives standard anchor props (including `href`) and
 * is responsible for bridging to your router's API:
 *
 * @example React Router integration
 * ```tsx
 * import { Link as ReactRouterLink } from "react-router-dom";
 *
 * const AppLink = forwardRef<HTMLAnchorElement, LinkComponentProps>(
 *   ({ href, ...rest }, ref) => (
 *     <ReactRouterLink ref={ref} to={href ?? ""} {...rest} />
 *   ),
 * );
 *
 * <LinkProvider component={AppLink}>
 *   <App />
 * </LinkProvider>
 * ```
 *
 * @example Next.js integration
 * ```tsx
 * import NextLink from "next/link";
 *
 * const AppLink = forwardRef<HTMLAnchorElement, LinkComponentProps>(
 *   (props, ref) => <NextLink ref={ref} {...props} />,
 * );
 *
 * <LinkProvider component={AppLink}>
 *   <App />
 * </LinkProvider>
 * ```
 */
export function LinkProvider({
  component,
  children,
}: {
  component?: ForwardLinkComponent;
  children: ReactNode;
}) {
  return (
    <LinkComponentContext.Provider value={component ?? DefaultLinkComponent}>
      {children}
    </LinkComponentContext.Provider>
  );
}

export type { LinkComponentProps };
